sqlMap.select:
SELECT * FROM ( SELECT A.DEPTNO, A.PARENT_DEPT_NO, GET_DEPT_NAME_RESUME(A.DEPTNO,#interLanguage:VARCHAR#,#interCpnyID:VARCHAR#,CASE WHEN #RESUME_NO:VARCHAR# IS NULL THEN (SELECT MAX( NO ) FROM ORG_RESUME_INFO WHERE CPNY_ID = #interCpnyID:VARCHAR# AND ACTIVITY <> 0) ELSE #RESUME_NO:VARCHAR# END) DEPTNAME, NVL(B.LOCAL_NAME,'Trống') LOCAL_NAME, A.MANAGER_EMP_ID, NVL(A.MANAGER_EMP_ID,'VACANCY') VACANCY, NVL(B.EMPID,'Trống') EMPID, get_global_name(B.POST_GRADE_NO,#interLanguage:VARCHAR#) POST_GRADE_NAME, get_global_name(B.EMP_OFFICE,#interLanguage:VARCHAR#) EMP_OFFICE_NAME, B.STATUS_CODE, get_global_name(B.STATUS_CODE,#interLanguage:VARCHAR#) STATUS_CODE_NAME, GET_GLOBAL_NAME(B.POSITION_NO, #interLanguage:VARCHAR#) POSITION_NO_NAME, A.IS_PART_TIME, TO_CHAR(A.UPDATE_DATE,'DD/MM/YYYY HH24:MI') UPDATE_DATE, GET_UPDATED_INFO(A.UPDATED_BY) || ' ' || A.UPDATED_IP UPDATED_BY, A.DEPT_LEVEL, A.ORDERNO FROM ORG_INFO A, ORG_EMPLOYEE B WHERE A.MANAGER_EMP_ID = B.PERSON_ID(+) AND A.RESUME_NO = B.RESUME_NO(+) AND A.CPNY_ID = B.CPNY_ID(+) AND A.CPNY_ID = #interCpnyID:VARCHAR# AND A.ACTIVITY = 1
( B.LOCAL_NAME LIKE UPPER('%$KEY$%') OR B.EMPID LIKE UPPER('%$KEY$%') OR B.CHINESE_PINYIN LIKE UPPER('%$KEY$%') )
A.RESUME_NO = #RESUME_NO:VARCHAR#
A.RESUME_NO = (SELECT MAX( NO ) FROM ORG_RESUME_INFO WHERE CPNY_ID = #interCpnyID:VARCHAR# AND ACTIVITY <> 0)
A.MANAGER_EMP_ID IN ( SELECT MANAGER_EMP_ID FROM ORG_INFO WHERE RESUME_NO = #RESUME_NO:VARCHAR# AND CPNY_ID = #interCpnyID:VARCHAR# AND IS_PART_TIME <> '1' AND MANAGER_EMP_ID IS NOT NULL AND ACTIVITY = 1 GROUP BY MANAGER_EMP_ID HAVING COUNT(1) > 1 ) ORDER BY MANAGER_EMP_ID
A.MANAGER_EMP_ID IS NULL ORDER BY DEPTNO
A.MANAGER_EMP_ID IN ( SELECT MANAGER_EMP_ID FROM ORG_INFO ORG WHERE ORG.RESUME_NO = #RESUME_NO:VARCHAR# AND ORG.CPNY_ID = #interCpnyID:VARCHAR# AND ORG.IS_PART_TIME = 1 AND ORG.ACTIVITY = 1 AND ORG.MANAGER_EMP_ID NOT IN ( SELECT MANAGER_EMP_ID FROM ORG_INFO ORG1 WHERE ORG1.RESUME_NO = #RESUME_NO:VARCHAR# AND ORG1.CPNY_ID = #interCpnyID:VARCHAR# AND ORG1.IS_PART_TIME <> 1 AND ACTIVITY = 1 ) ) ORDER BY MANAGER_EMP_ID
)
) START WITH DEPTNO = #DEPTNO:VARCHAR# CONNECT BY PRIOR DEPTNO = PARENT_DEPT_NO
) START WITH PARENT_DEPT_NO = '0' CONNECT BY PRIOR DEPTNO = PARENT_DEPT_NO ORDER SIBLINGS BY ORDERNO
